package com.google.gson.stream;

import java.io.*;
import java.io.Closeable;
import java.io.Flushable;
import java.io.IOException;
import java.io.StringWriter;
import java.io.Writer;
import java.math.*;
import java.util.*;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import org.mockito.Mockito;
import static org.junit.Assert.*;

public class JsonWriter_value_TriageGen2Test {

    private JsonWriter jsonWriter;
    private StringWriter stringWriter;

    @Before
    public void setUp() throws Exception {
        stringWriter = new StringWriter();
        jsonWriter = new JsonWriter(stringWriter);
    }

    @Test
    public void testValue_nullInput() throws IOException {
        JsonWriter result = jsonWriter.value(null);
        assertTrue(result != null);
        assertEquals("null", stringWriter.toString().trim());
    }

    @Test
    public void testValue_nonNullInput() throws IOException {
        String input = "testValue";
        JsonWriter result = jsonWriter.value(input);
        assertTrue(result != null);
        assertEquals("\"testValue\"", stringWriter.toString().trim());
    }

    @Test(expected = IOException.class)
    public void testValue_throwsIOException() throws IOException {
        JsonWriter mockWriter = Mockito.spy(jsonWriter);
        Mockito.doThrow(new IOException()).when(mockWriter).beforeValue(false);
        mockWriter.value("testValue");
    }

    @Test
    public void testValue_emptyString() throws IOException {
        JsonWriter result = jsonWriter.value("");
        assertTrue(result != null);
        assertEquals("\"\"", stringWriter.toString().trim());
    }

    @Test
    public void testValue_specialCharacters() throws IOException {
        String input = "test\nValue";
        JsonWriter result = jsonWriter.value(input);
        assertTrue(result != null);
        assertEquals("\"test\\nValue\"", stringWriter.toString().trim());
    }

    @Test
    public void testValue_withIndent() throws IOException {
        jsonWriter.setIndent("  ");
        String input = "testValue";
        JsonWriter result = jsonWriter.value(input);
        assertTrue(result != null);
        assertEquals("\"testValue\"", stringWriter.toString().trim());
    }

    @Test
    public void testValue_htmlSafe() throws IOException {
        jsonWriter.setHtmlSafe(true);
        String input = "<testValue>";
        JsonWriter result = jsonWriter.value(input);
        assertTrue(result != null);
        assertEquals("\"&lt;testValue&gt;\"", stringWriter.toString().trim());
    }

    @Test
    public void testValue_serializeNulls() throws IOException {
        jsonWriter.setSerializeNulls(true);
        JsonWriter result = jsonWriter.value(null);
        assertTrue(result != null);
        assertEquals("null", stringWriter.toString().trim());
    }

    @Test
    public void testValue_afterBeginArray() throws IOException {
        jsonWriter.beginArray();
        String input = "insideArray";
        JsonWriter result = jsonWriter.value(input);
        assertTrue(result != null);
        assertEquals("[\"insideArray\"]", stringWriter.toString().trim());
    }

    @Test
    public void testValue_afterBeginObject() throws IOException {
        jsonWriter.beginObject();
        jsonWriter.name("key");
        String input = "insideObject";
        JsonWriter result = jsonWriter.value(input);
        assertTrue(result != null);
        assertEquals("{\"key\":\"insideObject\"}", stringWriter.toString().trim());
    }

    @Test
    public void testValue_afterEndObject() throws IOException {
        jsonWriter.endObject();
        String input = "afterEndObject";
        JsonWriter result = jsonWriter.value(input);
        assertTrue(result != null);
        assertEquals("null,\"afterEndObject\"", stringWriter.toString().trim());
    }

    @Test
    public void testValue_afterEndArray() throws IOException {
        jsonWriter.endArray();
        String input = "afterEndArray";
        JsonWriter result = jsonWriter.value(input);
        assertTrue(result != null);
        assertEquals("null,\"afterEndArray\"", stringWriter.toString().trim());
    }
}
